for k, d in H.items():
    p = P[k]; name = p['home']
    shutil.copy(os.path.join(S, 'body/_Home.html'), os.path.join(S, 'body/%s.html' % name))
    data = {kk: d[kk] for kk in ['greet', 'sub', 'quick', 'kpis', 'q', 'head', 'rows', 'alerts']}
    js = '  renderVals() {\n    return Object.assign({ nav: this.navItems(%r) }, this.home(%s));\n  }\n' % (name, json.dumps(data, ensure_ascii=False))
    open(os.path.join(S, 'js/%s.js' % name), 'w').write(js)
    lines.append('\t'.join([name, p['name'] + ' home', p['name'] + ' / Home', 'Home · ' + p['name'], p['user'], d['role'], p['init'], k]))
open(os.path.join(S, 'homes.tsv'), 'w').write('\n'.join(lines) + '\n')
